package com.example

/**
 * Grade 11 Buddhism Syllabus Question Bank for Live Exam Hall.
 * Covers Terms 1, 2, and 3 with 60 distinct syllabus topic slots per term.
 * Permutes slots with coprime 7 so each paper presents all 60 syllabus points in unique sequence,
 * and provides distinct question variations across papers 1 to 30.
 */
object BuddhismGrade11QuestionBank {

  fun getQuestion(term: Int, paperIdx: Int, qNum: Int): MockExamQuestion {
    val cleanPaper = if (paperIdx in 1..30) paperIdx else 1
    val cleanQ = if (qNum in 1..60) qNum else 1
    val effectiveSlot = ((cleanQ - 1 + (cleanPaper - 1) * 7) % 60) + 1
    return when (term) {
      1 -> getTerm1Question(cleanPaper, cleanQ, effectiveSlot)
      2 -> getTerm2Question(cleanPaper, cleanQ, effectiveSlot)
      else -> getTerm3Question(cleanPaper, cleanQ, effectiveSlot)
    }
  }

  // ==========================================================================
  // GRADE 11 - TERM 1 (Slots 1 to 60)
  // ==========================================================================
  private fun getTerm1Question(paperIdx: Int, qNum: Int, slot: Int): MockExamQuestion {
    val v = paperIdx - 1
    val (topic, quad) = when (slot) {
      in 1..6 -> "සම්මා සම්බුද්ධ චරිතය සහ පාරිශුද්ධත්වය" to run {
        val list = listOf(
          Quad("සිද්ධාර්ථ බෝසතාණන් වහන්සේ සය වසරක් මුළුල්ලේ ශරීරයට දැඩි දුක් දෙමින් කළ ව්‍රතය කුමක්ද?", listOf("දුෂ්කර ක්‍රියාව (Dushkara Kriya)", "මධ්‍යම ප්‍රතිපදාව", "ප්‍රථම ධ්‍යානය", "ආනාපානසතිය"), 1, "උරුවෙල් දනව්වේ සේනානි නිගමයේදී අත්ථකිලමථානුයෝගය අත්හදා බලමින් දුෂ්කර ක්‍රියා කළහ."),
          Quad("බුද්ධත්වයට පත්වීමෙන් පසු දෙවන සතියේදී තමාට සෙවණ දුන් ජය ශ්‍රී මහා බෝධීන් වහන්සේ දෙස නොසැලෙන ඇසින් බලා සිටිමින් පෑ උතුම් ගුණය කුමක්ද?", listOf("කෘතවේදීත්වය (අනිමිසලෝචන පූජාව)", "වීරත්වය", "ධෛර්යය", "ඉවසීම"), 1, "අජීවී බෝධි වෘක්ෂයට පවා කෘතඥතාවය පළ කරමින් ලොවටම උතුම් ආදර්ශයක් සැපයූහ."),
          Quad("සම්මා සම්බුද්ධත්වයට පත්වූ සත් සතිය අතරින් පස්වන සතිය ගත කළ ස්ථානය කුමක්ද?", listOf("අජපාල නිග්‍රෝධ මූලය (එඬේර නුග රුක මුල)", "මුචලින්ද නාගදරණය", "රාජායතන මූලය", "රතනඝරය"), 1, "අජපාල නුග රුක මුලදී තණ්හා, රතී, රඟා යන මාර දූතියන් පරාජය කළහ."),
          Quad("බුදුරදුන්ගේ ශරීරයෙන් සවණක් ඝන බුද්ධ රශ්මි මාලාවන් විහිදී ගියේ සත් සතියේ කුමන සතියේදීද?", listOf("හතරවන සතියේ (රතනඝරයේදී අභිධර්මය මෙනෙහි කරද්දී)", "පළමු සතියේ", "දෙවන සතියේ", "තුන්වන සතියේ"), 1, "හේතුඵල පට්ඨාන මහා ප්‍රකරණය ගැඹුරින් මෙනෙහි කරද්දී සිරුරෙන් ෂඩ්වර්ණ රශ්මි විහිදිණි."),
          Quad("බුදුරජාණන් වහන්සේගේ ආචාර සමාචාර ගුණය විදහා දක්වන ප්‍රකට ගුණාංගය කුමක්ද?", listOf("මුහුණට හමුවූ ඕනෑම කෙනෙකුට ප්‍රථමයෙන් කතා කිරීම (පුබ්බභාසී ගුණය)", "නිශ්ශබ්දව සිටීම", "අනුන් කතා කරන තුරු බලා සිටීම", "දැඩිව කතා කිරීම"), 1, "බුදුරදුන් ආගන්තුකයන් දුටු විට සිනහමුසු මුහුණින් පිළිසඳර කතාවෙහි යෙදුණහ."),
          Quad("බුද්ධත්වයෙන් පසු තමන් වහන්සේ ගුරු තනතුරෙහි තබා ගරු කළේ කා හටද?", listOf("තමා අවබෝධ කරගත් ශ්‍රී සද්ධර්මයට (ධර්ම රත්නයට)", "දෙවියන්ට", "ආලාර කාලාම තවුසාට", "බ්‍රහ්මයාට"), 1, "ලොව තමාට වඩා උසස් කෙනෙකු නැති බැවින් තමා අවබෝධ කරගත් ධර්මයට ගරු කළහ.")
        )
        list[(slot - 1 + v).mod(list.size)]
      }
      in 7..12 -> "සූවිසි මහා ගුණය (බුද්ධ, ධම්ම, සංඝ)" to run {
        val list = listOf(
          Quad("නමෝ තස්ස භගවතෝ අරහතෝ... යන නමස්කාර පාඨයේ එන 'අරහං' බුද්ධ ගුණයේ අර්ථය කුමක්ද?", listOf("සියලු කෙලෙසුන් කෙරෙන් දුරුවූ හෙයින් සහ රහසින්වත් පව් නොකළ හෙයින්", "ලෝකය දන්නා හෙයින්", "දෙවියන්ට ශාස්තෘ වූ හෙයින්", "භාග්‍යවන්ත වූ හෙයින්"), 1, "කෙලෙස් සතුරන් නැසූ බැවින්ද, රහසින් පව් නොකරන බැවින්ද, ලෝකයාගේ පූජාවට සුදුසු බැවින්ද අරහං නම් වේ."),
          Quad("ගුරු උපදේශයකින් තොරව තමන් වහන්සේ විසින්ම චතුරාර්ය සත්‍යය අවබෝධ කරගත් බව දැක්වෙන බුද්ධ ගුණය කුමක්ද?", listOf("සම්මා සම්බුද්ධෝ (Samma Sambuddho)", "විජ්ජාචරණසම්පන්නෝ", "සුගතෝ", "ලෝකවිදූ"), 1, "තමා විසින්ම සියලු ධර්මයන් මැනවින් අවබෝධ කරගත් බැවින් සම්මා සම්බුද්ධ නම් වේ."),
          Quad("ධර්ම රත්නයේ ගුණ 6 අතුරින් 'අකාලිකෝ' (Akaliko) යන්නෙන් අදහස් වන්නේ කුමක්ද?", listOf("කල් නොයවා එම මොහොතේදීම ප්‍රතිඵල ලබාදිය හැකි බව", "කාලයක් ගතවී ප්‍රතිඵල දීම", "පරලොවදී පමණක් විපාක දීම", "කාලය නොදන්නා බව"), 1, "ධර්ම මාර්ගයේ යෙදෙන ඕනෑම කෙනෙකුට කාල භේදයකින් තොරව ක්ෂණිකව විපාක ලබාදේ."),
